CREATE TABLE calendar_sources(id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,configuration jsonb NOT NULL DEFAULT '{}',enabled boolean NOT NULL DEFAULT true,last_sync timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,name));
CREATE TABLE calendar_events(id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),source text NOT NULL,uid text NOT NULL,title text NOT NULL DEFAULT '',starts_at timestamptz,ends_at timestamptz,raw text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,source,uid));
CREATE INDEX calendar_events_owner_start ON calendar_events(owner_id,starts_at);
